1	// End-to-end regression coverage for the homepage draft-save race:
2	// after clicking save, the user keeps typing while waiting for the response.
3	// Those later keystrokes must neither be lost when the save succeeds nor be
4	// falsely reported as saved. Scenarios exercise the real form, status text,
5	// draft list, a second save and reopening the draft — never just the API.
6	//
7	// Run: node test/run.mjs   (CHROME_BIN can override the browser executable)
8	import assert from 'node:assert/strict';
9	import { setTimeout as sleep } from 'node:timers/promises';
10	import { Browser } from './cdp.mjs';
11	import { TestServer } from './server.mjs';
12	import { RawHttp, splitFrames } from './httpraw.mjs';
13	import * as ui from './ui.mjs';
14	
15	const tests = [];
16	function test(name, fn) { tests.push({ name, fn }); }
17	
18	// Poll the server directly until it has persisted at least `count` articles.
19	// Used with the save gate's capture mode, where the save request really
20	// reaches the server and only its response is parked in the page.
21	async function waitForServerArticles(server, count) {
22	  const deadline = Date.now() + 5000;
23	  for (;;) {
24	    const articles = await server.listArticles();
25	    if (articles.length >= count) return articles;
26	    if (Date.now() > deadline) throw new Error(`server did not persist ${count} articles in time`);
27	    await sleep(25);
28	  }
29	}
30	
31	async function seed(server, fields) {
32	  const res = await server.api('/api/articles', {
33	    method: 'POST',
34	    body: JSON.stringify({ summary: '', ...fields }),
35	  });
36	  assert.equal(res.status, 201, `seed failed: ${res.status}`);
37	  return (await res.json()).article;
38	}
39	
40	// Seeds happen out-of-band (as if saved in another tab), so the page must
41	// reload its list before the user can click the new draft's 编辑 button.
42	async function seedAndReload(server, page, fields) {
43	  const article = await seed(server, fields);
44	  await ui.reload(page);
45	  return article;
46	}
47	
48	async function freshContext(browser) {
49	  const server = await TestServer.start();
50	  const page = await ui.open(browser, server.url);
51	  return { server, page };
52	}
53	
54	async function closeContext({ server, page }, browser) {
55	  ui.assertNoPageErrors(page);
56	  await browser.closePage(page);
57	  await server.stop();
58	}
59	
60	// Body text exercising plain-text fidelity: Chinese, other scripts, newlines,
61	// blank lines and HTML-like markup that must never be parsed or executed.
62	const RICH_BODY = '多行正文第一段\n\n中间空行\n\n中文 English café 日本語 العربية 한국어\n\n'
63	  + '<script>alert(1)</script>\n<img src=x onerror=alert(2)><b>不应加粗</b>\n<div>末段</div>';
64	
65	async function getArticle(server, id) {
66	  const res = await server.api(`/api/articles/${id}`);
67	  assert.equal(res.status, 200);
68	  return (await res.json()).article;
69	}
70	
71	// An out-of-band update, exactly as if another tab saved the draft.
72	async function updateOut(server, id, fields, version) {
73	  const res = await server.api(`/api/articles/${id}`, {
74	    method: 'PUT',
75	    body: JSON.stringify({ summary: '', ...fields, version }),
76	  });
77	  const data = await res.json().catch(() => ({}));
78	  return { status: res.status, article: data.article, error: data.error };
79	}
80	
81	// Puts the page into the post-409 state: it opened v1, holds `mine` in the
82	// form, and another tab has since saved v2, so the page's save is rejected
83	// with the side-by-side conflict comparison.
84	async function stageStaleConflict(server, page, v1, mine, v2) {
85	  const article = await seedAndReload(server, page, v1);
86	  await ui.clickEdit(page, v1.title);
87	  await ui.waitLoadedDraft(page);
88	  await ui.fill(page, mine);
89	  const up = await updateOut(server, article.id, v2, 1);
90	  assert.equal(up.status, 200, `other-tab update should succeed: ${up.status} ${up.error || ''}`);
91	  await ui.clickSave(page);
92	  await ui.waitForStatus(page, '409', 'err');
93	  await ui.waitConflictShown(page);
94	  return { article, saved: up.article };
95	}
96	
97	// The comparison columns render with textContent: markup-like text must appear
98	// verbatim and must not create elements or run handlers (no dialog may fire).
99	async function assertConflictPlainText(page) {
100	  const injected = await page.eval(
101	    `document.querySelectorAll('#conflict-box .ver script,#conflict-box .ver img,#conflict-box .ver b').length`);
102	  assert.equal(injected, 0);
103	  assert.equal(page.dialogs.length, 0);
104	}
105	
106	// ---------------------------------------------------------------------------
107	// 1. Editing an existing draft: save, keep typing during the wait, save again.
108	// ---------------------------------------------------------------------------
109	test('编辑态保存等待期间继续输入：内容保留、只提示未保存字段、再次保存生效、重开一致', async (browser) => {
110	  const ctx = await freshContext(browser);
111	  const { server, page } = ctx;
112	  try {
113	    const a = await seedAndReload(server, page, {
114	      title: '原标题',
115	      summary: '原摘要',
116	      body: '原正文第一段\n\n原正文第二段',
117	    });
118	
119	    // 用户实际操作：打开已有草稿（正文以单篇接口返回为准）。
120	    await ui.clickEdit(page, '原标题');
121	    await ui.waitLoadedDraft(page);
122	    let s = await ui.state(page);
123	    assert.equal(s.saveBtnText, '保存修改');
124	    assert.deepEqual(s.form, { title: '原标题', summary: '原摘要', body: '原正文第一段\n\n原正文第二段' });
125	    assert.equal(s.bannerId, a.id);
126	
127	    // 提交标题、摘要、正文。
128	    await ui.fill(page, {
129	      title: '  修改后的标题  ',
130	      summary: '实际提交的摘要 <b>x</b>',
131	      body: '实际提交的正文第一段\n\n实际提交的正文第二段',
132	    });
133	    await ui.gateOn(page);
134	    await ui.clickSave(page);
135	    await ui.waitSavingPending(page, 1);
136	
137	    // 等待响应期间：标题不动，摘要补写、正文重写（含换行、空行、多语言、类 HTML 文本）。
138	    await ui.fill(page, {
139	      summary: '等待期间补写的摘要',
140	      body: '等待期间的正文\n\n空行保留\n\n中文 English café 日本語 العربية\n\n<html>原样文本</html>',
141	    });
142	    // 保存进行中重复点击不会产生第二次提交。
143	    await ui.clickSave(page);
144	    s = await ui.state(page);
145	    assert.equal(s.saveDisabled, true);
146	    assert.deepEqual(await page.eval(`__qtest.gateState()`), { enabled: true, hits: 1, pending: 1 });
147	    // 成功返回前列表仍是旧内容：不能提前显示尚未保存成功的东西。
148	    assert.equal(s.cards[0].title, '原标题');
149	    assert.equal(s.cards[0].summary, '原摘要');
150	
151	    await ui.releaseSaves(page);
152	    await ui.gateOff(page);
153	    await ui.waitForStatus(page, '尚未保存', 'warn');
154	    s = await ui.state(page);
155	
156	    // 明确指出哪些字段还有未保存修改（标题不在其列）。
157	    assert.match(s.statusText, /但摘要、正文在保存期间又被修改/);
158	    assert.ok(!s.statusText.includes('标题在保存期间'));
159	    // 表单保留等待期间输入的当前值，一个字符都不动。
160	    assert.equal(s.form.title, '修改后的标题'); // 本次提交的标题按规则去首尾空白
161	    assert.equal(s.form.summary, '等待期间补写的摘要');
162	    assert.equal(s.form.body,
163	      '等待期间的正文\n\n空行保留\n\n中文 English café 日本語 العربية\n\n<html>原样文本</html>');
164	    // 仍编辑同一篇草稿。
165	    assert.equal(s.formEditing, true);
166	    assert.equal(s.bannerHidden, false);
167	    assert.equal(s.bannerId, a.id);
168	    assert.equal(s.bannerTitle, '修改后的标题');
169	    assert.equal(s.saveBtnText, '保存修改');
170	    assert.equal(s.saveDisabled, false);
171	    // 列表反映的是本次实际提交并保存的标题与摘要，不是等待期间的新输入。
172	    assert.equal(s.listCount, 1);
173	    assert.equal(s.cards[0].title, '修改后的标题');
174	    assert.equal(s.cards[0].summary, '实际提交的摘要 <b>x</b>');
175	    assert.equal(s.cards[0].editing, true);
176	    // 类 HTML 的摘要按文本渲染，不执行任何标记。
177	    assert.equal(await page.eval(`document.querySelectorAll('#article-list .summary').length`), 1);
178	    assert.equal(await page.eval(`document.querySelector('#article-list .summary b')`), null);
179	
180	    // 服务端状态：同一篇草稿，版本推进，标识/创建时间/状态不变，存的是实际提交内容。
181	    let saved = await (await server.api(`/api/articles/${a.id}`)).json();
182	    assert.equal(saved.article.id, a.id);
183	    assert.equal(saved.article.createdAt, a.createdAt);
184	    assert.equal(saved.article.status, 'draft');
185	    assert.equal(saved.article.version, 2);
186	    assert.equal(saved.article.title, '修改后的标题');
187	    assert.equal(saved.article.summary, '实际提交的摘要 <b>x</b>');
188	    assert.equal(saved.article.body, '实际提交的正文第一段\n\n实际提交的正文第二段');
189	
190	    // 再次点击“保存修改”：刚才保留的内容才成为已保存内容，且不能误报冲突。
191	    await ui.clickSave(page);
192	    await ui.waitForStatus(page, '修改已保存', 'ok');
193	    s = await ui.state(page);
194	    assert.equal(s.conflictHidden, true);
195	    assert.equal(s.cards[0].summary, '等待期间补写的摘要');
196	    saved = await (await server.api(`/api/articles/${a.id}`)).json();
197	    assert.equal(saved.article.version, 3);
198	    assert.equal(saved.article.id, a.id);
199	    assert.equal(saved.article.createdAt, a.createdAt);
200	    assert.equal(saved.article.body,
201	      '等待期间的正文\n\n空行保留\n\n中文 English café 日本語 العربية\n\n<html>原样文本</html>');
202	    assert.equal(s.listCount, 1);
203	
204	    // 再次打开草稿：完整正文（含空行与类 HTML 文本）以单篇接口返回为准被载入。
205	    await ui.clickCancel(page);
206	    await ui.clickEdit(page, '修改后的标题');
207	    await ui.waitLoadedDraft(page);
208	    s = await ui.state(page);
209	    assert.equal(s.form.body, saved.article.body);
210	    assert.equal(s.form.summary, '等待期间补写的摘要');
211	    assert.equal(s.bannerId, a.id);
212	
213	    // 重开后基于最新版本保存，仍应成功（版本基准来自单篇接口，不报 409）。
214	    await ui.fill(page, { body: `${saved.article.body}\n重开后再补充一行` });
215	    await ui.clickSave(page);
216	    await ui.waitForStatus(page, '修改已保存', 'ok');
217	    saved = await (await server.api(`/api/articles/${a.id}`)).json();
218	    assert.equal(saved.article.version, 4);
219	    assert.equal(saved.article.body,
220	      '等待期间的正文\n\n空行保留\n\n中文 English café 日本語 العربية\n\n<html>原样文本</html>\n重开后再补充一行');
221	    assert.equal((await server.listArticles()).length, 1);
222	  } finally {
223	    await closeContext(ctx, browser);
224	  }
225	});
