227	// ---------------------------------------------------------------------------
228	// 2. During the wait the user may clear summary/body entirely.
229	// ---------------------------------------------------------------------------
230	test('编辑态等待期间清空摘要和正文：清空被保留并明确提示，再次保存真的清空', async (browser) => {
231	  const ctx = await freshContext(browser);
232	  const { server, page } = ctx;
233	  try {
234	    const a = await seedAndReload(server, page, { title: '清空测试', summary: '原有摘要', body: '原有正文' });
235	    await ui.clickEdit(page, '清空测试');
236	    await ui.waitLoadedDraft(page);
237	
238	    await ui.fill(page, { title: '清空测试-改', summary: '提交的摘要', body: '提交的正文' });
239	    await ui.gateOn(page);
240	    await ui.clickSave(page);
241	    await ui.waitSavingPending(page, 1);
242	    await ui.fill(page, { summary: '', body: '' });
243	    await ui.releaseSaves(page);
244	    await ui.gateOff(page);
245	
246	    await ui.waitForStatus(page, '尚未保存', 'warn');
247	    let s = await ui.state(page);
248	    assert.match(s.statusText, /但摘要、正文在保存期间又被修改/);
249	    assert.deepEqual(s.form, { title: '清空测试-改', summary: '', body: '' });
250	    assert.equal(s.cards[0].title, '清空测试-改');
251	    assert.equal(s.cards[0].summary, '提交的摘要'); // 列表只显示已保存内容
252	    assert.equal(s.bannerId, a.id);
253	
254	    await ui.clickSave(page);
255	    await ui.waitForStatus(page, '修改已保存', 'ok');
256	    const saved = await (await server.api(`/api/articles/${a.id}`)).json();
257	    assert.equal(saved.article.summary, '');
258	    assert.equal(saved.article.body, '');
259	    assert.equal(saved.article.version, 3);
260	    s = await ui.state(page);
261	    assert.equal(s.cards[0].summary, null); // 空摘要不渲染摘要段
262	    assert.equal(s.listCount, 1);
263	  } finally {
264	    await closeContext(ctx, browser);
265	  }
266	});
