268	// ---------------------------------------------------------------------------
269	// 2b. Any field may keep changing during the wait — including the title. A
270	//     kept title change must be named as unsaved (raw value with surrounding
271	//     spaces retained); the second save trims and persists it.
272	// ---------------------------------------------------------------------------
273	test('编辑态等待期间连标题也改：三个未保存字段都点名，保留原值，再次保存标题按规则去空白', async (browser) => {
274	  const ctx = await freshContext(browser);
275	  const { server, page } = ctx;
276	  try {
277	    const a = await seedAndReload(server, page, { title: '旧标题', summary: '旧摘要', body: '旧正文' });
278	    await ui.clickEdit(page, '旧标题');
279	    await ui.waitLoadedDraft(page);
280	
281	    await ui.fill(page, { title: '提交标题', summary: '提交摘要', body: '提交正文' });
282	    await ui.gateOn(page);
283	    await ui.clickSave(page);
284	    await ui.waitSavingPending(page, 1);
285	    await ui.fill(page, {
286	      title: '  等待期间的新标题  ',
287	      summary: '等待期间的新摘要',
288	      body: '等待期间的新正文',
289	    });
290	    await ui.releaseSaves(page);
291	    await ui.gateOff(page);
292	
293	    await ui.waitForStatus(page, '尚未保存', 'warn');
294	    let s = await ui.state(page);
295	    // 明确点名所有仍有未保存修改的字段，顺序固定为标题、摘要、正文。
296	    assert.match(s.statusText, /但标题、摘要、正文在保存期间又被修改/);
297	    // 表单保留等待期间输入的当前值，连首尾空白都原样保留。
298	    assert.deepEqual(s.form, {
299	      title: '  等待期间的新标题  ',
300	      summary: '等待期间的新摘要',
301	      body: '等待期间的新正文',
302	    });
303	    // 列表只显示本次实际保存的内容。
304	    assert.equal(s.cards[0].title, '提交标题');
305	    assert.equal(s.cards[0].summary, '提交摘要');
306	    assert.equal(s.bannerId, a.id);
307	    assert.equal(s.bannerTitle, '提交标题');
308	
309	    await ui.clickSave(page);
310	    await ui.waitForStatus(page, '修改已保存', 'ok');
311	    const saved = await (await server.api(`/api/articles/${a.id}`)).json();
312	    assert.equal(saved.article.title, '等待期间的新标题'); // 第二次保存才去空白落库
313	    assert.equal(saved.article.summary, '等待期间的新摘要');
314	    assert.equal(saved.article.body, '等待期间的新正文');
315	    assert.equal(saved.article.id, a.id);
316	    assert.equal(saved.article.createdAt, a.createdAt);
317	    assert.equal(saved.article.version, 3);
318	    s = await ui.state(page);
319	    assert.equal(s.cards[0].title, '等待期间的新标题');
320	    assert.equal(s.listCount, 1);
321	    assert.equal(s.form.title, '等待期间的新标题'); // 保存后表单同步为规范值
322	  } finally {
323	    await closeContext(ctx, browser);
324	  }
325	});
