327	// ---------------------------------------------------------------------------
328	// 3. Unsaved detection uses final field values vs. what was actually saved:
329	//    edits reverted during the wait, and a title that only differs by the
330	//    server's end trimming, must not be reported as unsaved.
331	// ---------------------------------------------------------------------------
332	test('等待期间改动后恢复原值/标题等价于服务端规范值：不误报未保存', async (browser) => {
333	  const ctx = await freshContext(browser);
334	  const { server, page } = ctx;
335	  try {
336	    await seedAndReload(server, page, { title: '基准标题', summary: '基准摘要', body: '基准正文' });
337	    await ui.clickEdit(page, '基准标题');
338	    await ui.waitLoadedDraft(page);
339	
340	    await ui.fill(page, { title: '  规范标题  ', summary: '提交摘要', body: '提交正文' });
341	    await ui.gateOn(page);
342	    await ui.clickSave(page);
343	    await ui.waitSavingPending(page, 1);
344	    // 标题先改成别的、再改成与服务端保存后相同的文字（去空白后的“规范标题”）。
345	    await ui.fill(page, { title: '暂时的标题', body: '暂时的正文' });
346	    await ui.fill(page, { title: '规范标题', body: '提交正文' }); // 正文改回提交值
347	    await ui.releaseSaves(page);
348	    await ui.gateOff(page);
349	
350	    await ui.waitForStatus(page, '修改已保存', 'ok');
351	    const s = await ui.state(page);
352	    assert.equal(s.statusKind, 'ok');
353	    assert.ok(!s.statusText.includes('尚未保存'));
354	    assert.deepEqual(s.form, { title: '规范标题', summary: '提交摘要', body: '提交正文' });
355	    assert.equal(s.bannerTitle, '规范标题');
356	    assert.equal(s.listCount, 1);
357	    assert.equal(s.cards[0].title, '规范标题');
358	    const articles = await server.listArticles();
359	    assert.equal(articles[0].version, 2);
360	  } finally {
361	    await closeContext(ctx, browser);
362	  }
363	});
364	
365	// ---------------------------------------------------------------------------
366	// 4. New draft: type more during the wait -> one draft only, form associates
367	//    with the created article in editing mode; later saves update it.
368	// ---------------------------------------------------------------------------
369	test('新建草稿等待期间补写：只产生一篇、自动关联进入编辑态、后续更新同一篇', async (browser) => {
370	  const ctx = await freshContext(browser);
371	  const { server, page } = ctx;
372	  try {
373	    await ui.fill(page, {
374	      title: '  新草稿标题  ',
375	      summary: '首版摘要',
376	      body: '首版正文',
377	    });
378	    await ui.gateOn(page);
379	    await ui.clickSave(page);
380	    await ui.waitSavingPending(page, 1);
381	    await ui.fill(page, {
382	      body: '首版正文\n\n等待期间补写：中文 English café\n\n<html>按文本处理</html>',
383	    });
384	    await ui.releaseSaves(page);
385	    await ui.gateOff(page);
386	
387	    await ui.waitForStatus(page, '尚未保存', 'warn');
388	    let s = await ui.state(page);
389	    assert.match(s.statusText, /但正文在保存期间又被修改/);
390	    assert.equal(s.listCount, 1);
391	    assert.equal(s.cards[0].title, '新草稿标题');
392	    assert.equal(s.cards[0].summary, '首版摘要');
393	    assert.equal(s.cards[0].editing, true);
394	    // 表单关联到刚创建的文章并进入编辑状态。
395	    assert.equal(s.formEditing, true);
396	    assert.equal(s.saveBtnText, '保存修改');
397	    assert.equal(s.cancelHidden, false);
398	    assert.ok(s.bannerId);
399	    assert.equal(s.form.body, '首版正文\n\n等待期间补写：中文 English café\n\n<html>按文本处理</html>');
400	    assert.equal(s.form.title, '新草稿标题');
401	
402	    const articles1 = await server.listArticles();
403	    assert.equal(articles1.length, 1);
404	    assert.equal(articles1[0].version, 1);
405	    assert.equal(articles1[0].title, '新草稿标题');
406	    assert.equal(articles1[0].body, '首版正文');
407	    const createdId = articles1[0].id;
408	    assert.equal(s.bannerId, createdId);
409	
410	    // 后续保存更新这篇文章，而不是再新建一篇。
411	    await ui.clickSave(page);
