1710	// ===========================================================================
1711	// 请求体大小限制的服务端回归保障（上限 5×1024×1024 字节）。
1712	// 上面的页面测试已覆盖“超长英文正文触发保存失败后保留输入”；这里固定服务端
1713	// 对“实际发送的整份 JSON 请求体 UTF-8 字节数”的判断本身：
1714	//   - 标题、摘要、正文、更新时的 version 与 JSON 结构全部计入；
1715	//   - 合法请求恰好达到上限成功，超出哪怕一个字节也拒绝；
1716	//   - 中文等多字节文字按字节而非字符计数，换行（JSON 中转义为 \n）同样计入；
1717	//   - 正文自身未超限、加上其他字段整份请求才超限，也算超限；
1718	//   - Content-Length 与分块传输遵守同一上限、同一结论；分块时前帧尚在限内、
1719	//     后帧才让累计字节超限，客户端仍能读到完整、可解析的 400 与非空 error，
1720	//     而不是连接中断或残缺响应，连接随后还能继续使用；
1721	//   - 拒绝新建不新增记录；拒绝更新不改动原文章任何字段，其他草稿不受影响；
1722	//   - 合法新建 201/版本1，合法更新 200/标识与创建时间不变/版本只加一，
1723	//     多语言与换行内容经现有 GET 读取入口原样取回，标题按规则去首尾空白。
1724	// 这些场景直接驱动 HTTP（原始 TCP 套接字精确控制线上字节与分块帧），持久化
1725	// 内容仍只通过现有读取入口核对，不改变首页编辑方式与已公开的保存行为。
1726	// ===========================================================================
1727	
1728	const MAX_BODY_BYTES = 5 * 1024 * 1024;
1729	
1730	// 以固定字段顺序构造与页面一致的负载（{title,summary,body}[,version]），
1731	// 把 padField 用 padUnit 重复填充（剩余字节用 ASCII 'a' 补齐），使整份 JSON
1732	// 请求体经 UTF-8 编码后恰好为 size 个字节。换行等需 JSON 转义的字符按其
1733	// 在线上 JSON 文本中的实际字节数计量。
1734	function buildPaddedObject(version, padField, pad) {
1735	  const obj = { title: 't', summary: 's', body: 'b' };
1736	  if (version !== null) obj.version = version; // version 始终位于 body 之后
1737	  obj[padField] = pad; // 更新已有键，不改变字段顺序
1738	  return obj;
1739	}
1740	
1741	function sizedObjectBody(size, { version = null, padField = 'body', padUnit = 'x' } = {}) {
1742	  const overhead = Buffer.byteLength(JSON.stringify(buildPaddedObject(version, padField, '')), 'utf8');
1743	  const unitWire = Buffer.byteLength(JSON.stringify(buildPaddedObject(version, padField, padUnit)), 'utf8') - overhead;
1744	  assert.ok(unitWire > 0);
1745	  const units = Math.floor((size - overhead) / unitWire);
1746	  let pad = padUnit.repeat(units);
1747	  let body = Buffer.from(JSON.stringify(buildPaddedObject(version, padField, pad)), 'utf8');
1748	  if (body.length < size) {
1749	    pad += 'a'.repeat(size - body.length); // 差额必小于 unitWire，1 字节 ASCII 可精确补齐
1750	    body = Buffer.from(JSON.stringify(buildPaddedObject(version, padField, pad)), 'utf8');
1751	  }
1752	  assert.equal(body.length, size, `无法精确拼出 ${size} 字节的请求体（实际 ${body.length}）`);
1753	  return body;
1754	}
1755	
1756	// 统一核对超限拒绝：完整可读的 400、非空且明确说明“超过允许大小”的 error。
1757	function assertTooLargeResponse(res, transport) {
1758	  assert.equal(res.status, 400, `${transport}：超过上限哪怕一个字节也必须是 400，实际 ${res.status}`);
1759	  assert.match(res.headers['content-type'] || '', /application\/json/, `${transport}：400 应为 JSON`);
1760	  const declared = res.headers['content-length'];
1761	  assert.notEqual(declared, undefined, `${transport}：400 必须带 Content-Length`);
1762	  assert.equal(res.body.length, Number(declared),
1763	    `${transport}：必须读到完整 400 响应体（${res.body.length}/${declared}），不能是连接中断或残缺响应`);
1764	  let data;
1765	  assert.doesNotThrow(() => { data = JSON.parse(res.body.toString('utf8')); },
1766	    `${transport}：400 响应体必须是可解析的 JSON`);
1767	  assert.ok(typeof data.error === 'string' && data.error.trim() !== '',
1768	    `${transport}：error 必须非空`);
1769	  assert.match(data.error, /allowed size|too large|exceed/i,
1770	    `${transport}：error 必须明确说明超过允许大小：${data.error}`);
1771	  return data.error;
1772	}
