92	(function () {
93	  'use strict';
94	  var form = document.getElementById('draft-form');
95	  var titleInput = document.getElementById('title');
96	  var summaryInput = document.getElementById('summary');
97	  var bodyInput = document.getElementById('body');
98	  var saveBtn = document.getElementById('save-btn');
99	  var cancelBtn = document.getElementById('cancel-btn');
100	  var statusEl = document.getElementById('status');
101	  var editBanner = document.getElementById('edit-banner');
102	  var conflictBox = document.getElementById('conflict-box');
103	  var listEl = document.getElementById('article-list');
104	  var emptyTip = document.getElementById('empty-tip');
105	  var listNotice = document.getElementById('list-notice');
106	  var articles = [];
107	  // 首次列表读取是否已结束（成功或失败）。结果到达前用户保存的草稿绝不能
108	  // 被随后到达的旧快照覆盖；失败时这些已保存卡片也要继续保留。
109	  var listLoaded = false;
