167	      card.appendChild(meta);
168	      if (summaryText) card.appendChild(summary);
169	      var actions = document.createElement('p');
170	      actions.className = 'actions';
171	      var editBtn = document.createElement('button');
172	      editBtn.type = 'button';
173	      editBtn.className = 'secondary';
174	      editBtn.textContent = isEditing ? '正在编辑' : '编辑';
