(function () {
  'use strict';
  var form = document.getElementById('draft-form');
  var titleInput = document.getElementById('title');
  var summaryInput = document.getElementById('summary');
  var bodyInput = document.getElementById('body');
  var saveBtn = document.getElementById('save-btn');
  var cancelBtn = document.getElementById('cancel-btn');
  var statusEl = document.getElementById('status');
  var editBanner = document.getElementById('edit-banner');
  var conflictBox = document.getElementById('conflict-box');
  var listEl = document.getElementById('article-list');
  var emptyTip = document.getElementById('empty-tip');
  var listNotice = document.getElementById('list-notice');
  var articles = [];
  // 首次列表读取是否已结束（成功或失败）。结果到达前用户保存的草稿绝不能
  // 被随后到达的旧快照覆盖；失败时这些已保存卡片也要继续保留。
  var listLoaded = false;
  // 首次列表读取失败的具体原因；空字符串表示当前没有失败。
  var listError = '';
  var saving = false;
  // null = 新建草稿模式；对象 = 正在编辑的服务端版本 {id,title,summary,body,version}
  var editing = null;
  // 冲突对照区当前的操作按钮，读取最新内容期间需暂时禁用
  var conflictActionButtons = [];

  function setStatus(text, kind) {
    statusEl.textContent = text || '';
    statusEl.className = 'status' + (kind ? ' ' + kind : '');
  }
  function setEmpty(text, kind) {
    emptyTip.textContent = text || '';
    emptyTip.className = 'empty' + (kind ? ' ' + kind : '');
    emptyTip.hidden = !text;
  }
  function hideConflict() {
    conflictBox.hidden = true;
    conflictBox.textContent = '';
    conflictActionButtons = [];
  }
  function setConflictActionsDisabled(disabled) {
    conflictActionButtons.forEach(function (btn) { btn.disabled = disabled; });
  }
  function formatTime(iso) {
    var d = new Date(iso);
    return isNaN(d.getTime()) ? String(iso) : d.toLocaleString();
  }
  function render() {
    var sorted = articles.slice().sort(function (a, b) {
      var ta = a && a.createdAt ? String(a.createdAt) : '';
      var tb = b && b.createdAt ? String(b.createdAt) : '';
      if (ta !== tb) return ta < tb ? 1 : -1;
      return 0;
    });
    listEl.textContent = '';
    sorted.forEach(function (article) {
      var isEditing = editing && editing.id === article.id;
      var card = document.createElement('article');
      card.className = 'draft' + (isEditing ? ' editing' : '');
      var h = document.createElement('h3');
      h.textContent = article.title == null ? '' : String(article.title);
      if (isEditing) {
        var tag = document.createElement('span');
        tag.className = 'editing-tag';
        tag.textContent = '编辑中';
        h.appendChild(tag);
      }
      var meta = document.createElement('p');
      meta.className = 'meta';
      meta.textContent = '创建时间：' + formatTime(article.createdAt);
      var summary = document.createElement('p');
      summary.className = 'summary';
      var summaryText = article.summary == null ? '' : String(article.summary);
      summary.textContent = summaryText;
      card.appendChild(h);
      card.appendChild(meta);
      if (summaryText) card.appendChild(summary);
      var actions = document.createElement('p');
      actions.className = 'actions';
      var editBtn = document.createElement('button');
      editBtn.type = 'button';
      editBtn.className = 'secondary';
      editBtn.textContent = isEditing ? '正在编辑' : '编辑';
      editBtn.disabled = !!isEditing;
      editBtn.addEventListener('click', function () { startEdit(article.id); });
      actions.appendChild(editBtn);
      card.appendChild(actions);
      var li = document.createElement('li');
      li.appendChild(card);
      listEl.appendChild(li);
    });
    renderListChrome(sorted.length);
  }

  function setNotice(text) {
    listNotice.textContent = text || '';
    listNotice.hidden = !text;
  }

  // 列表区在“加载中 / 已取得完整列表 / 加载失败”三种状态下分别该显示什么。
  // 失败时绝不说成“还没有保存的草稿”：有本页面已保存的卡片就说明列表可能
  // 不完整、保存成功的草稿仍然保留；一张卡片都没有时也只显示真实失败原因。
  function renderListChrome(count) {
    listEl.setAttribute('aria-busy', listLoaded ? 'false' : 'true');
    if (listError) {
      setEmpty('');
      setNotice('草稿列表加载失败，完整列表尚未取得：' + listError
        + (count > 0 ? '。以下是本页面已经保存成功的草稿，仍然保留并可正常打开编辑。' : ''));
    } else if (!listLoaded) {
      setNotice('');
      setEmpty(count === 0 ? '草稿加载中…' : '');
    } else {
      setNotice('');
      setEmpty(count === 0 ? '还没有保存的草稿。' : '');
    }
  }

  function versionNumberOf(article) {
    var v = article && article.version;
    return typeof v === 'number' && isFinite(v) ? v : 0;
  }

  // 首次列表结果与本页面状态合并，而不是整体替换：
  // - 本页面已保存成功的文章必须保留；标题相同但标识不同的文章仍是两条
  //   记录，结果带回的其他文章也一并并入；
  // - 同一标识只保留一条：迟到的初始结果是页面上最旧的一份快照，同 id 时
  //   只有版本不旧于本地已知版本的数据才能覆盖，列表不能退回旧标题、摘要
  //   或版本（版本缺失按 0 处理，兼容旧数据）；
  // - 结果按创建时间倒序排列仍由 render 处理。
  // 合并只影响列表数据，绝不触碰表单输入、编辑对象与已取得的版本基准。
  function mergeInitialList(incoming) {
    var merged = articles.slice();
    var indexById = Object.create(null);
    merged.forEach(function (article, i) { indexById[String(article.id)] = i; });
    incoming.forEach(function (incomingArticle) {
      if (!incomingArticle || incomingArticle.id == null) return;
      var key = String(incomingArticle.id);
      var localIndex = Object.prototype.hasOwnProperty.call(indexById, key)
        ? indexById[key] : -1;
      if (localIndex < 0) {
        indexById[key] = merged.length;
        merged.push(incomingArticle);
        return;
      }
      if (versionNumberOf(incomingArticle) < versionNumberOf(merged[localIndex])) {
        return; // 迟到结果里的旧版本：保留本地已有的较新已保存内容
      }
      merged[localIndex] = incomingArticle;
    });
    articles = merged;
  }

  function load() {
    return fetch('/api/articles', { headers: { accept: 'application/json' } })
      .then(function (r) {
        if (!r.ok) {
          return r.json().catch(function () { return null; }).then(function (data) {
            throw new Error(data && data.error ? data.error : ('HTTP ' + r.status));
          });
        }
        return r.json();
      })
      .then(function (data) {
        var incoming = data && Array.isArray(data.articles) ? data.articles : [];
        mergeInitialList(incoming);
        listError = '';
        listLoaded = true;
        render();
      })
      .catch(function (err) {
        // 首次列表读取失败：保留本页面已成功保存并显示的草稿，绝不用空
        // 结果替换列表，也不把“列表加载失败”说成保存失败或“没有草稿”。
        listError = err && err.message ? err.message : String(err);
        listLoaded = true;
        render();
      });
  }

  function setSaving(on, label) {
    saving = on;
    saveBtn.disabled = on;
    saveBtn.textContent = label || (editing ? '保存修改' : '保存草稿');
    cancelBtn.disabled = on;
  }

  function enterCreateMode(message, kind) {
    editing = null;
    form.reset();
    form.classList.remove('editing');
    editBanner.hidden = true;
    editBanner.textContent = '';
    hideConflict();
    cancelBtn.hidden = true;
    saveBtn.textContent = '保存草稿';
    setStatus(message || '', kind || '');
    render();
  }

  function renderEditBanner(article) {
    editBanner.textContent = '';
    var line1 = document.createElement('div');
    line1.textContent = '正在编辑草稿：';
    var code = document.createElement('code');
    code.textContent = String(article.title);
    line1.appendChild(code);
    var line2 = document.createElement('div');
    line2.className = 'meta';
    line2.textContent = '创建时间：' + formatTime(article.createdAt) + ' · 标识：' + String(article.id);
    editBanner.appendChild(line1);
    editBanner.appendChild(line2);
  }

  function applyEditingState(article) {
    editing = {
      id: article.id,
      title: article.title,
      summary: article.summary,
      body: article.body,
      version: article.version
    };
    // 列表同步为本次载入的已保存内容，使该草稿的标题、摘要与“编辑中”标识
    // 与载入结果一致（载入的可能比列表缓存更新）。
    var idx = -1;
    for (var i = 0; i < articles.length; i++) {
      if (articles[i] && articles[i].id === article.id) { idx = i; break; }
    }
    if (idx >= 0) articles[idx] = article; else articles.push(article);
    titleInput.value = article.title == null ? '' : String(article.title);
    summaryInput.value = article.summary == null ? '' : String(article.summary);
    bodyInput.value = article.body == null ? '' : String(article.body);
    form.classList.add('editing');
    renderEditBanner(article);
    editBanner.hidden = false;
    cancelBtn.hidden = false;
    saveBtn.textContent = '保存修改';
    hideConflict();
    setStatus('已载入该草稿当前保存的内容，可以开始修改。', null);
    render();
    titleInput.focus();
  }

  function isDirty() {
    if (!editing) {
      return titleInput.value !== '' || summaryInput.value !== '' || bodyInput.value !== '';
    }
    return titleInput.value !== editing.title
      || summaryInput.value !== editing.summary
      || bodyInput.value !== editing.body;
  }

  function formSnapshot() {
    return {
      title: titleInput.value,
      summary: summaryInput.value,
      body: bodyInput.value
    };
  }

