    await ui.reload(page);
    await ui.fill(page, { title: '新建未保存标题', summary: '新建未保存摘要', body: '新建未保存正文' });

    // 选择“取消”：不读取，新建表单与输入不变。
    await ui.readGateOn(page);
    await ui.setConfirm(page, 'cancel');
