// Find a list card by its exact title (titles are unique within a scenario).
function cardByTitle(s, title) {
  const card = s.cards.find((c) => c.title === title);
  assert.ok(card, `列表中应存在标题为 ${JSON.stringify(title)} 的卡片`);
  return card;
}

