test('编辑态打开另一篇草稿读取返回404/500/网络失败：显示具体原因、保留等待期间输入与原编辑状态、恢复可操作', async (browser) => {
  const ctx = await freshContext(browser);
  const { server, page } = ctx;
  try {
    const a = await seed(server, { title: '原文草稿', summary: '原文摘要', body: '原文正文' });
